--
-- Name: is_project_director(uuid, uuid); Type: FUNCTION; Schema: projects; Owner: gs_admin
--

CREATE FUNCTION projects.is_project_director(p_project_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM projects.project_users
    WHERE project_id = p_project_id
      AND user_id = p_user_id
      AND role_in_project = 'DIRECTOR'
  );
$$;


