--
-- Name: mv_closer_daily_kpis; Type: MATERIALIZED VIEW; Schema: sales; Owner: gs_admin
--

CREATE MATERIALIZED VIEW sales.mv_closer_daily_kpis AS
 SELECT project_id,
    closer_id,
    date(created_at) AS kpi_date,
    count(*) FILTER (WHERE (status = ANY (ARRAY['APPROVED'::text, 'PURCHASE_APPROVED'::text, 'COMPLETE'::text, 'PURCHASE_COMPLETE'::text, 'APROBADO'::text, 'COMPLETA'::text, 'COMPLETO'::text, 'Aprobado'::text, 'Completo'::text]))) AS count_sales,
    sum(amount) FILTER (WHERE (status = ANY (ARRAY['APPROVED'::text, 'PURCHASE_APPROVED'::text, 'COMPLETE'::text, 'PURCHASE_COMPLETE'::text, 'APROBADO'::text, 'COMPLETA'::text, 'COMPLETO'::text, 'Aprobado'::text, 'Completo'::text]))) AS sum_gross
   FROM sales.sales
  WHERE (closer_id IS NOT NULL)
  GROUP BY project_id, closer_id, (date(created_at))
  WITH NO DATA;


ALTER MATERIALIZED VIEW sales.mv_closer_daily_kpis OWNER TO gs_admin;

--
-- Name: mv_product_daily_kpis; Type: MATERIALIZED VIEW; Schema: sales; Owner: gs_admin
--

CREATE MATERIALIZED VIEW sales.mv_product_daily_kpis AS
 SELECT project_id,
    product_name,
    product_id,
    date(created_at) AS kpi_date,
    count(*) FILTER (WHERE (status = ANY (ARRAY['APPROVED'::text, 'PURCHASE_APPROVED'::text, 'COMPLETE'::text, 'PURCHASE_COMPLETE'::text, 'APROBADO'::text, 'COMPLETA'::text, 'COMPLETO'::text, 'Aprobado'::text, 'Completo'::text]))) AS count_sales,
    sum(amount) FILTER (WHERE (status = ANY (ARRAY['APPROVED'::text, 'PURCHASE_APPROVED'::text, 'COMPLETE'::text, 'PURCHASE_COMPLETE'::text, 'APROBADO'::text, 'COMPLETA'::text, 'COMPLETO'::text, 'Aprobado'::text, 'Completo'::text]))) AS sum_gross
   FROM sales.sales
  WHERE (product_name IS NOT NULL)
  GROUP BY project_id, product_name, product_id, (date(created_at))
  WITH NO DATA;


ALTER MATERIALIZED VIEW sales.mv_product_daily_kpis OWNER TO gs_admin;

--
-- Name: mv_project_daily_metrics; Type: MATERIALIZED VIEW; Schema: sales; Owner: gs_admin
--

CREATE MATERIALIZED VIEW sales.mv_project_daily_metrics AS
 SELECT project_id,
    date(created_at) AS kpi_date,
    sum(amount) FILTER (WHERE (status = ANY (ARRAY['APPROVED'::text, 'PURCHASE_APPROVED'::text, 'COMPLETE'::text, 'PURCHASE_COMPLETE'::text, 'APROBADO'::text, 'COMPLETA'::text, 'COMPLETO'::text, 'Aprobado'::text, 'Completo'::text]))) AS facturacion_bruta,
    sum((amount * ((installments - 1))::numeric)) FILTER (WHERE ((status = ANY (ARRAY['APPROVED'::text, 'PURCHASE_APPROVED'::text, 'COMPLETE'::text, 'PURCHASE_COMPLETE'::text, 'APROBADO'::text, 'COMPLETA'::text, 'COMPLETO'::text, 'Aprobado'::text, 'Completo'::text])) AND (installments > 1))) AS facturacion_proxima,
    count(*) FILTER (WHERE (status = ANY (ARRAY['APPROVED'::text, 'PURCHASE_APPROVED'::text, 'COMPLETE'::text, 'PURCHASE_COMPLETE'::text, 'APROBADO'::text, 'COMPLETA'::text, 'COMPLETO'::text, 'Aprobado'::text, 'Completo'::text]))) AS ventas_totales,
    count(*) FILTER (WHERE ((status = ANY (ARRAY['APPROVED'::text, 'PURCHASE_APPROVED'::text, 'COMPLETE'::text, 'PURCHASE_COMPLETE'::text, 'APROBADO'::text, 'COMPLETA'::text, 'COMPLETO'::text, 'Aprobado'::text, 'Completo'::text])) AND (closer_id IS NULL))) AS marketing_ventas,
    sum(amount) FILTER (WHERE ((status = ANY (ARRAY['APPROVED'::text, 'PURCHASE_APPROVED'::text, 'COMPLETE'::text, 'PURCHASE_COMPLETE'::text, 'APROBADO'::text, 'COMPLETA'::text, 'COMPLETO'::text, 'Aprobado'::text, 'Completo'::text])) AND (closer_id IS NULL))) AS marketing_facturacion,
    count(*) FILTER (WHERE ((status = ANY (ARRAY['APPROVED'::text, 'PURCHASE_APPROVED'::text, 'COMPLETE'::text, 'PURCHASE_COMPLETE'::text, 'APROBADO'::text, 'COMPLETA'::text, 'COMPLETO'::text, 'Aprobado'::text, 'Completo'::text])) AND (closer_id IS NOT NULL))) AS comercial_ventas,
    sum(amount) FILTER (WHERE ((status = ANY (ARRAY['APPROVED'::text, 'PURCHASE_APPROVED'::text, 'COMPLETE'::text, 'PURCHASE_COMPLETE'::text, 'APROBADO'::text, 'COMPLETA'::text, 'COMPLETO'::text, 'Aprobado'::text, 'Completo'::text])) AND (closer_id IS NOT NULL))) AS comercial_facturacion,
    count(*) FILTER (WHERE ((status = ANY (ARRAY['APPROVED'::text, 'PURCHASE_APPROVED'::text, 'COMPLETE'::text, 'PURCHASE_COMPLETE'::text, 'APROBADO'::text, 'COMPLETA'::text, 'COMPLETO'::text, 'Aprobado'::text, 'Completo'::text])) AND (upper(COALESCE(external_txn_id, ''::text)) ~~ 'HP%'::text))) AS hotmart_ventas,
    sum(amount) FILTER (WHERE ((status = ANY (ARRAY['APPROVED'::text, 'PURCHASE_APPROVED'::text, 'COMPLETE'::text, 'PURCHASE_COMPLETE'::text, 'APROBADO'::text, 'COMPLETA'::text, 'COMPLETO'::text, 'Aprobado'::text, 'Completo'::text])) AND (upper(COALESCE(external_txn_id, ''::text)) ~~ 'HP%'::text))) AS hotmart_facturacion,
    count(*) FILTER (WHERE ((status = ANY (ARRAY['APPROVED'::text, 'PURCHASE_APPROVED'::text, 'COMPLETE'::text, 'PURCHASE_COMPLETE'::text, 'APROBADO'::text, 'COMPLETA'::text, 'COMPLETO'::text, 'Aprobado'::text, 'Completo'::text])) AND (upper(COALESCE(external_txn_id, ''::text)) !~~ 'HP%'::text))) AS externas_ventas,
    sum(amount) FILTER (WHERE ((status = ANY (ARRAY['APPROVED'::text, 'PURCHASE_APPROVED'::text, 'COMPLETE'::text, 'PURCHASE_COMPLETE'::text, 'APROBADO'::text, 'COMPLETA'::text, 'COMPLETO'::text, 'Aprobado'::text, 'Completo'::text])) AND (upper(COALESCE(external_txn_id, ''::text)) !~~ 'HP%'::text))) AS externas_facturacion,
    sum(commission_amount) FILTER (WHERE (status = ANY (ARRAY['APPROVED'::text, 'PURCHASE_APPROVED'::text, 'COMPLETE'::text, 'PURCHASE_COMPLETE'::text, 'APROBADO'::text, 'COMPLETA'::text, 'COMPLETO'::text, 'Aprobado'::text, 'Completo'::text]))) AS sum_commission
   FROM sales.sales
  GROUP BY project_id, (date(created_at))
  WITH NO DATA;


ALTER MATERIALIZED VIEW sales.mv_project_daily_metrics OWNER TO gs_admin;

--
-- Name: MATERIALIZED VIEW mv_project_daily_metrics; Type: COMMENT; Schema: sales; Owner: gs_admin
--

COMMENT ON MATERIALIZED VIEW sales.mv_project_daily_metrics IS 'KPIs diarios por proyecto. Hotmart = código de transacción HP*; externas = ventas sin código Hotmart. Marketing = sin closer; comercial = con closer.';


